WITH return_summary AS ( SELECT cr.cr_returning_customer_sk, cr.cr_returning_addr_sk, SUM(cr.cr_return_amount) AS total_return_amount, SUM(cr.cr_net_loss) AS total_net_loss, COUNT(*) AS return_cnt FROM catalog_returns cr GROUP BY cr.cr_returning_customer_sk, cr.cr_returning_addr_sk HAVING SUM(cr.cr_return_amount) > 1000 ) SELECT r.cr_returning_customer_sk, r.total_return_amount, r.total_net_loss, r.return_cnt, c.c_first_name, c.c_last_name, ca.ca_state, ROW_NUMBER() OVER (PARTITION BY ca.ca_state ORDER BY r.total_return_amount DESC) AS state_rank FROM return_summary r JOIN customer c ON r.cr_returning_customer_sk = c.c_customer_sk JOIN customer_address ca ON r.cr_returning_addr_sk = ca.ca_address_sk ORDER BY r.total_return_amount DESC LIMIT 200
